{"command":"python3 - <<'PY'
import json

def h(n, src, aux, dst):
    if n == 0:
        return []
    return h(n-1, src, dst, aux) + [[n, src, dst]] + h(n-1, aux, src, dst)

moves = h(8,0,1,2)
# split into chunks of 25
chunks = [moves[i:i+25] for i in range(0, len(moves), 25)]
for i,ch in enumerate(chunks):
    print(f'Chunk {i+1}/{len(chunks)}:')
    print(json.dumps(ch))
